ALTER TABLE public.characters
  ADD COLUMN IF NOT EXISTS slug text,
  ADD COLUMN IF NOT EXISTS posicionamento text,
  ADD COLUMN IF NOT EXISTS promessa_central text,
  ADD COLUMN IF NOT EXISTS biografia_interna text,
  ADD COLUMN IF NOT EXISTS dores_publico text,
  ADD COLUMN IF NOT EXISTS desejos_publico text,
  ADD COLUMN IF NOT EXISTS categorias_prioritarias text,
  ADD COLUMN IF NOT EXISTS pilares_conteudo text,
  ADD COLUMN IF NOT EXISTS gatilhos_persuasao text,
  ADD COLUMN IF NOT EXISTS formatos_roteiro text,
  ADD COLUMN IF NOT EXISTS estilo_interpretacao text,
  ADD COLUMN IF NOT EXISTS identidade_visual_canonica text,
  ADD COLUMN IF NOT EXISTS identity_version text NOT NULL DEFAULT '1.0',
  ADD COLUMN IF NOT EXISTS ativo boolean NOT NULL DEFAULT true;

CREATE UNIQUE INDEX IF NOT EXISTS characters_slug_key ON public.characters (slug) WHERE slug IS NOT NULL;

